using System.Net.Http.Json;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Simulates web search results. Replace with a real search API (Bing, Google, Tavily)
/// by setting the AI:SearchEndpoint and AI:SearchApiKey configuration values.
/// </summary>
public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    public static async Task<string> SearchAsync(string query)
    {
        var searchEndpoint = Environment.GetEnvironmentVariable("AI__SearchEndpoint");
        var searchApiKey = Environment.GetEnvironmentVariable("AI__SearchApiKey");

        if (!string.IsNullOrEmpty(searchEndpoint) && !string.IsNullOrEmpty(searchApiKey))
        {
            return await LiveSearchAsync(query, searchEndpoint, searchApiKey);
        }

        // Simulated search results for demonstration purposes
        return GetSimulatedResults(query);
    }

    private static async Task<string> LiveSearchAsync(string query, string endpoint, string apiKey)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get,
            $"{endpoint.TrimEnd('/')}/v7.0/search?q={Uri.EscapeDataString(query)}&count=5");
        request.Headers.Add("Ocp-Apim-Subscription-Key", apiKey);

        var response = await HttpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var results = new List<string>();

        if (json.TryGetProperty("webPages", out var webPages) &&
            webPages.TryGetProperty("value", out var values))
        {
            foreach (var item in values.EnumerateArray().Take(5))
            {
                var name = item.GetProperty("name").GetString();
                var snippet = item.GetProperty("snippet").GetString();
                var url = item.GetProperty("url").GetString();
                results.Add($"- {name}\n  {snippet}\n  Source: {url}");
            }
        }

        return results.Count > 0
            ? string.Join("\n\n", results)
            : "No results found.";
    }

    private static string GetSimulatedResults(string query)
    {
        var lowerQuery = query.ToLowerInvariant();

        if (lowerQuery.Contains("quantum"))
        {
            return """
                Search results for: "{query}"

                1. "Quantum Computing Breakthroughs in 2026" - Nature Physics
                   IBM announced a 4,000+ qubit processor achieving quantum advantage on optimization
                   problems. Error correction rates improved by 10x using new surface code techniques.
                   Source: https://nature.com/articles/quantum-2026

                2. "Google's Willow Chip Advances" - MIT Technology Review
                   Google's latest quantum chip demonstrates below-threshold error rates, enabling
                   sustained logical qubit operations for over 1 hour. Applications in drug discovery
                   and materials science are now commercially viable.
                   Source: https://technologyreview.com/quantum-willow-2026

                3. "Microsoft Topological Qubits Reach Milestone" - IEEE Spectrum
                   Microsoft's topological qubit approach achieved 99.9% gate fidelity,
                   with plans for a 1000-logical-qubit machine by 2028.
                   Source: https://spectrum.ieee.org/microsoft-topological-2026

                4. "Quantum Cloud Services Market Report" - Gartner
                   The quantum-computing-as-a-service market grew 300% YoY, with AWS Braket,
                   Azure Quantum, and IBM Quantum Network leading enterprise adoption.
                   Source: https://gartner.com/quantum-market-2026

                5. "Post-Quantum Cryptography Standards Finalized" - NIST
                   NIST released final standards for quantum-resistant algorithms. Migration
                   timelines now mandatory for US government systems by 2028.
                   Source: https://nist.gov/pqc-standards-2026
                """.Replace("{query}", query);
        }

        return $"""
            Search results for: "{query}"

            1. "Recent Developments in {query}" - Wikipedia
               Comprehensive overview of the latest advances and key milestones in this field.
               Multiple research groups have published significant findings in 2026.
               Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}

            2. "Expert Analysis: {query}" - Scientific American
               Experts weigh in on the current state of research and future directions.
               Funding has increased 40% year-over-year with major institutional backing.
               Source: https://scientificamerican.com/article/{Uri.EscapeDataString(query)}

            3. "Industry Applications of {query}" - TechCrunch
               Several startups and major tech companies are applying this research
               commercially. Market size estimated at $50B by 2030.
               Source: https://techcrunch.com/{Uri.EscapeDataString(query)}-applications
            """;
    }
}

namespace ResearchAgent;

/// <summary>
/// Simple in-memory note-taking service for the research agent.
/// </summary>
public sealed class NoteService
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void AddNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been taken yet.";
        }

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[{i + 1}] {n.Title} (recorded at {n.Timestamp:HH:mm:ss UTC})\n{n.Content}"));
    }

    public int Count => _notes.Count;
}

