using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddSingleton<NoteService>();

builder.Services.AddChatClient(chatBuilder => chatBuilder
    .UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18",
        builder.Configuration["AI:Endpoint"] is string endpoint ? new Uri(endpoint) : null,
        builder.Configuration["AI:ApiKey"]
            ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.")));

builder.Services.AddSingleton(sp =>
{
    var chatClient = sp.GetRequiredService<IChatClient>();
    var noteService = sp.GetRequiredService<NoteService>();
    var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

    var tools = new AITool[]
    {
        AIFunctionFactory.Create(
            ([Description("The search query to look up on the web")] string query) =>
            {
                return WebSearchTool.SearchAsync(query);
            },
            "web_search",
            "Searches the web for information on a given query and returns relevant results."),

